"""Clocked Scale-up PIFO simulation and closed-burst certificates."""

import bisect
import heapq
import json
import re
import sys


INPUT_LIMIT = 24 * 1024 * 1024
MAX_PACKETS = 120000
ID_RE = re.compile(r"[A-Za-z0-9_-]{1,32}")


class Invalid(Exception):
    pass


class Packet:
    __slots__ = (
        "id", "lane", "rank", "ordinal", "bank", "range", "slot",
        "pos", "admission_t",
    )

    def __init__(self, ident, lane, rank, ordinal, slot):
        self.id = ident
        self.lane = lane
        self.rank = rank
        self.ordinal = ordinal
        self.slot = slot
        self.bank = -1
        self.range = -1
        self.pos = -1
        self.admission_t = 0


def exact_object(value, fields):
    if type(value) is not dict or len(value) != len(fields):
        raise Invalid
    for key in fields:
        if key not in value:
            raise Invalid


def integer(value, low, high):
    if type(value) is not int or value < low or value > high:
        raise Invalid
    return value


def common_fields(obj):
    q = integer(obj["banks"], 1, 16)
    lanes = integer(obj["lanes"], 1, 8)
    limit = integer(obj["limit"], 1, 2147483648)
    borders = obj["borders"]
    if type(borders) is not list or not 2 <= len(borders) <= 33:
        raise Invalid
    for value in borders:
        if type(value) is not int:
            raise Invalid
    if borders[0] != 0 or borders[-1] != limit:
        raise Invalid
    for i in range(1, len(borders)):
        if borders[i] <= borders[i - 1]:
            raise Invalid
    return q, lanes, limit, list(borders)


def packet_data(value, lanes, limit, identifiers):
    exact_object(value, ("id", "lane", "rank"))
    ident = value["id"]
    if type(ident) is not str or ID_RE.fullmatch(ident) is None:
        raise Invalid
    if ident in identifiers:
        raise Invalid
    identifiers.add(ident)
    lane = integer(value["lane"], 0, lanes - 1)
    rank = integer(value["rank"], 0, limit - 1)
    return ident, lane, rank


def make_packet(data, ordinal, rank_slots):
    ident, lane, rank = data
    slot = rank_slots.get(rank, 0)
    rank_slots[rank] = slot + 1
    return Packet(ident, lane, rank, ordinal, slot)


def prepare_ranks(packets, rank_slots):
    positions = {rank: i for i, rank in enumerate(sorted(rank_slots))}
    for packet in packets:
        packet.pos = positions[packet.rank]
    return positions


def validate_stream(obj):
    exact_object(obj, (
        "mode", "banks", "lanes", "limit", "borders", "capacity",
        "epoch", "steps",
    ))
    q, lanes, limit, borders = common_fields(obj)
    capacity = integer(obj["capacity"], 1, 20000)
    epoch = integer(obj["epoch"], 0, 40000)
    raw_steps = obj["steps"]
    if type(raw_steps) is not list or len(raw_steps) > 40000:
        raise Invalid

    identifiers = set()
    rank_slots = {}
    packets = []
    steps = []
    previous_t = -1
    ordinal = 0
    for raw_step in raw_steps:
        exact_object(raw_step, ("t", "serve", "arrivals"))
        tick = integer(raw_step["t"], 0, 9007199254740991)
        if tick <= previous_t:
            raise Invalid
        previous_t = tick
        serve = raw_step["serve"]
        if type(serve) is not bool:
            raise Invalid
        raw_arrivals = raw_step["arrivals"]
        if (type(raw_arrivals) is not list or len(raw_arrivals) > lanes
                or ordinal + len(raw_arrivals) > MAX_PACKETS):
            raise Invalid
        data_by_lane = []
        used_lanes = set()
        for raw_packet in raw_arrivals:
            data = packet_data(raw_packet, lanes, limit, identifiers)
            lane = data[1]
            if lane in used_lanes:
                raise Invalid
            used_lanes.add(lane)
            data_by_lane.append(data)
        data_by_lane.sort(key=lambda data: data[1])
        arrivals = []
        for data in data_by_lane:
            packet = make_packet(data, ordinal, rank_slots)
            ordinal += 1
            packets.append(packet)
            arrivals.append(packet)
        steps.append((tick, serve, arrivals))

    prepare_ranks(packets, rank_slots)
    return {
        "banks": q, "lanes": lanes, "borders": borders,
        "capacity": capacity, "epoch": epoch, "steps": steps,
        "packets": packets, "rank_count": len(rank_slots),
    }


def validate_burst(obj):
    exact_object(obj, (
        "mode", "banks", "lanes", "limit", "borders", "start_bank",
        "packets",
    ))
    q, lanes, limit, borders = common_fields(obj)
    start_bank = integer(obj["start_bank"], 0, q - 1)
    raw_packets = obj["packets"]
    if type(raw_packets) is not list or len(raw_packets) > MAX_PACKETS:
        raise Invalid
    identifiers = set()
    rank_slots = {}
    packets = []
    for ordinal, raw_packet in enumerate(raw_packets):
        data = packet_data(raw_packet, lanes, limit, identifiers)
        packet = make_packet(data, ordinal, rank_slots)
        packets.append(packet)
    prepare_ranks(packets, rank_slots)
    return {
        "banks": q, "lanes": lanes, "borders": borders,
        "start_bank": start_bank, "packets": packets,
        "rank_count": len(rank_slots),
    }


class Fenwick:
    __slots__ = ("tree",)

    def __init__(self, size):
        self.tree = [0] * (size + 1)

    def add(self, position, amount):
        i = position + 1
        tree = self.tree
        size = len(tree)
        while i < size:
            tree[i] += amount
            i += i & -i

    def lower_sum(self, position):
        total = 0
        i = position
        tree = self.tree
        while i:
            total += tree[i]
            i -= i & -i
        return total


class Residents:
    """Heaps plus global rank and same-rank ordinal statistics."""

    def __init__(self, banks, packets, rank_count):
        self.heaps = [[] for _ in range(banks)]
        self.rank_counts = Fenwick(rank_count)
        self.rank_bits = {packet.rank: 0 for packet in packets}
        self.resident_count = 0

    def admit(self, packet, bank):
        packet.bank = bank
        heapq.heappush(
            self.heaps[bank], (packet.rank, packet.ordinal, packet)
        )
        self.rank_counts.add(packet.pos, 1)
        self.rank_bits[packet.rank] |= 1 << packet.slot
        self.resident_count += 1

    def depart(self, bank):
        entry = self.heaps[bank][0]
        packet = entry[2]
        rank = packet.rank
        bits = self.rank_bits[rank]
        bit = 1 << packet.slot

        rank_error = self.rank_counts.lower_sum(packet.pos)
        tie_overtakes = (bits & (bit - 1)).bit_count()
        comparable = self.resident_count - bits.bit_count()

        heapq.heappop(self.heaps[bank])
        self.rank_counts.add(packet.pos, -1)
        self.rank_bits[rank] = bits ^ bit
        self.resident_count -= 1
        return packet, rank_error, tie_overtakes, comparable


def range_for(rank, borders):
    return bisect.bisect_right(borders, rank) - 1


def initial_rr(ranges, lanes, banks):
    return [[(r + lane) % banks for lane in range(lanes)]
            for r in range(ranges)]


def controller(borders, weights, histogram, banks):
    ranges = len(weights)
    updated = [weights[r] // 2 + histogram[r] for r in range(ranges)]
    total = sum(updated)
    triggered = (
        total > 0 and ranges > 1 and
        (2 * ranges * min(updated) < total or
         ranges * max(updated) > 2 * total)
    )
    new_borders = borders
    new_weights = updated
    if triggered:
        smallest = min(updated)
        a = updated.index(smallest)
        if a == 0:
            left = a
            right = a + 1
        elif a == ranges - 1:
            left = a - 1
            right = a
        elif updated[a - 1] <= updated[a + 1]:
            left = a - 1
            right = a
        else:
            left = a
            right = a + 1

        temp_borders = list(borders)
        del temp_borders[right]
        temp_weights = list(updated)
        temp_weights[left] += temp_weights[right]
        del temp_weights[right]

        eligible = [
            r for r in range(ranges - 1)
            if temp_borders[r + 1] - temp_borders[r] >= 2
        ]
        if eligible:
            split = eligible[0]
            split_weight = temp_weights[split]
            for r in eligible[1:]:
                weight = temp_weights[r]
                if weight > split_weight:
                    split = r
                    split_weight = weight
            lo = temp_borders[split]
            hi = temp_borders[split + 1]
            middle = (lo + hi) // 2
            temp_borders.insert(split + 1, middle)
            left_weight = split_weight // 2
            temp_weights[split:split + 1] = [
                left_weight, split_weight - left_weight
            ]
            new_borders = temp_borders
            new_weights = temp_weights

    histogram[:] = [0] * ranges
    rr = initial_rr(ranges, controller.lanes, banks)
    return new_borders, new_weights, rr


def simulate_stream(config):
    banks = config["banks"]
    lanes = config["lanes"]
    borders = config["borders"]
    ranges = len(borders) - 1
    capacity = config["capacity"]
    epoch = config["epoch"]
    rr = initial_rr(ranges, lanes, banks)
    weights = [0] * ranges
    histogram = [0] * ranges
    residents = Residents(banks, config["packets"], config["rank_count"])

    # The controller is shared by the simulation but must use this request's L.
    controller.lanes = lanes

    next_bank = 0
    events = []
    attempted = 0
    accepted = 0
    departed = 0
    idle = 0
    inversions = 0
    tie_total = 0
    comparable_total = 0
    wait_sum = 0
    wait_max = 0

    for position, (tick, serve, arrivals) in enumerate(config["steps"]):
        update = None
        if epoch > 0 and position > 0 and position % epoch == 0:
            borders, weights, rr = controller(
                borders, weights, histogram, banks
            )
            update = {"borders": list(borders), "weights": list(weights)}

        service = None
        if serve:
            bank = next_bank
            next_bank = (next_bank + 1) % banks
            if residents.heaps[bank]:
                packet, error, ties, comparable = residents.depart(bank)
                departed += 1
                inversions += error
                tie_total += ties
                comparable_total += comparable
                wait = tick - packet.admission_t
                wait_sum += wait
                if wait > wait_max:
                    wait_max = wait
                departure = {
                    "id": packet.id, "rank_error": error,
                    "tie_overtakes": ties, "comparable": comparable,
                    "wait": wait,
                }
            else:
                idle += 1
                departure = None
            service = {"bank": bank, "packet": departure}

        arrival_results = []
        for packet in arrivals:
            attempted += 1
            rank_range = range_for(packet.rank, borders)
            histogram[rank_range] += 1
            bank = rr[rank_range][packet.lane]
            rr[rank_range][packet.lane] = (bank + 1) % banks
            ok = len(residents.heaps[bank]) < capacity
            if ok:
                packet.range = rank_range
                packet.admission_t = tick
                residents.admit(packet, bank)
                accepted += 1
            arrival_results.append({
                "id": packet.id, "range": rank_range, "bank": bank,
                "accepted": ok,
            })

        events.append({
            "t": tick, "update": update, "service": service,
            "arrivals": arrival_results,
            "sizes": [len(heap) for heap in residents.heaps],
        })

    queues = [
        [entry[2].id for entry in sorted(heap, key=lambda entry: entry[:2])]
        for heap in residents.heaps
    ]
    final = {
        "borders": list(borders), "weights": list(weights),
        "histogram": list(histogram), "rr": rr,
        "next_bank": next_bank, "queues": queues,
        "totals": {
            "attempted": attempted, "accepted": accepted,
            "dropped": attempted - accepted, "departed": departed,
            "idle": idle, "inversions": inversions,
            "tie_overtakes": tie_total, "comparable": comparable_total,
            "wait_sum": wait_sum, "wait_max": wait_max,
        },
    }
    return {"events": events, "final": final}


def simulate_burst(config):
    banks = config["banks"]
    lanes = config["lanes"]
    borders = config["borders"]
    packets = config["packets"]
    ranges = len(borders) - 1
    rr = initial_rr(ranges, lanes, banks)
    counts = [[0] * banks for _ in range(ranges)]
    residents = Residents(banks, packets, config["rank_count"])
    assignment = []

    for packet in packets:
        rank_range = range_for(packet.rank, borders)
        bank = rr[rank_range][packet.lane]
        rr[rank_range][packet.lane] = (bank + 1) % banks
        packet.range = rank_range
        residents.admit(packet, bank)
        counts[rank_range][bank] += 1
        assignment.append({"id": packet.id, "range": rank_range, "bank": bank})

    observed = [0] * ranges
    departures = []
    tick = 0
    idle = 0
    bank = config["start_bank"]
    while residents.resident_count:
        if residents.heaps[bank]:
            packet, error, ties, comparable = residents.depart(bank)
            departures.append({
                "t": tick, "bank": bank, "id": packet.id,
                "rank_error": error, "tie_overtakes": ties,
                "comparable": comparable,
            })
            if error > observed[packet.range]:
                observed[packet.range] = error
        else:
            idle += 1
        tick += 1
        bank = (bank + 1) % banks

    range_results = []
    prefix_population = 0
    for r in range(ranges):
        population = sum(counts[r])
        prefix_population += population
        if population == 0:
            bound = 0
        else:
            bound = min(
                prefix_population - 1,
                (banks - 1) * (r * lanes + max(counts[r])),
            )
        range_results.append({
