def reject_constant(_value):
    raise Invalid


def reject_float(_value):
    raise Invalid


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Invalid
        result[key] = value
    return result


def check_nesting(value):
    stack = [(value, 1)]
    while stack:
        current, depth = stack.pop()
        if type(current) is dict:
            if depth > 12:
                raise Invalid
            for child in current.values():
                if type(child) is dict or type(child) is list:
                    stack.append((child, depth + 1))
        elif type(current) is list:
            if depth > 12:
                raise Invalid
            for child in current:
                if type(child) is dict or type(child) is list:
                    stack.append((child, depth + 1))


def load_input():
    raw = sys.stdin.buffer.read(INPUT_LIMIT + 1)
    if len(raw) > INPUT_LIMIT:
        raise Invalid
    text = raw.decode("utf-8")
    try:
        value = json.loads(
            text, object_pairs_hook=unique_object,
            parse_constant=reject_constant, parse_float=reject_float,
        )
    except (ValueError, RecursionError):
        raise Invalid
    check_nesting(value)
    if type(value) is not dict:
        raise Invalid
    mode = value.get("mode")
    if mode == "stream":
        return "stream", validate_stream(value)
    if mode == "burst":
        return "burst", validate_burst(value)
    raise Invalid


def main():
    try:
        mode, config = load_input()
    except (Invalid, UnicodeError, ValueError, RecursionError):
        sys.stdout.write('{"error":"invalid input"}\n')
        return 2
    if mode == "stream":
        output = simulate_stream(config)
    else:
        output = simulate_burst(config)
    sys.stdout.write(json.dumps(
        output, ensure_ascii=False, allow_nan=False, separators=(",", ":")
    ))
    sys.stdout.write("\n")
    return 0


